//! 🪆️ Literal record binding protects completed fields and admits the borrowed domain census.
use super::*;
use semio_framework_dsl_record::FieldValue;
use semio_framework_dsl_record::RecordValue;
use semio_framework_dsl_record::DslField;
fn record(value:&FieldValue,last:u16)->Result<&RecordValue,ValueError>{let semio_framework_dsl_record::FieldValue::Record(value)=value else{return Err(invalid("native literal record required"))};closed(value,last)?;Ok(value)}
fn closed(value:&RecordValue,last:u16)->Result<(),ValueError>{if value.fields.keys().any(|id|*id>last){Err(invalid("native record has undeclared field"))}else{Ok(())}}
fn list(value:&RecordValue,id:u16)->Result<&[FieldValue],ValueError>{match value.get(id){Some(semio_framework_dsl_record::FieldValue::List(value))=>Ok(value),_=>Err(invalid("native literal ordered list required"))}}
fn scalar<T:DslField>(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<T,ValueError>{let out=c.scoped_stage(|c|{c.begin_stage(0)?;T::from_value_controlled(value.get(id).unwrap_or(&semio_framework_dsl_record::FieldValue::Absent),c)})?;c.step()?;Ok(out)}
fn optional_scalar<T:DslField>(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Option<T>,ValueError>{match value.get(id){None|Some(semio_framework_dsl_record::FieldValue::Absent)=>{c.step()?;Ok(None)},Some(_)=>scalar(value,id,c).map(Some)}}
fn text(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<String,ValueError>{let Some(semio_framework_dsl_record::FieldValue::Text(value))=value.get(id)else{return Err(invalid("native literal text required"))};let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(c.copy_text(value)?,close::<String>);c.step()?;Ok(out.take())}
fn optional_text(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{let out=match value.get(id){None|Some(semio_framework_dsl_record::FieldValue::Absent)=>None,Some(semio_framework_dsl_record::FieldValue::Text(value))=>Some(c.copy_text(value)?),_=>return Err(invalid("native optional literal text required"))};let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(out,close::<Option<String>>);c.step()?;Ok(out.take())}
fn collection<T:RetireOwned>(values:&[FieldValue],c:&mut NativeDecodeControl<'_>,mut bind:impl FnMut(&FieldValue,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Vec<T>,ValueError>{c.scoped_stage(|c|{c.begin_stage(values.len())?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(c.allocate_vec(values.len())?,close::<Vec<T>>);for value in values{out.as_mut().push(c.scoped_stage(|c|{c.begin_stage(0)?;bind(value,c)})?);c.step()?;}Ok(out.take())})}
fn texts(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Vec<String>,ValueError>{let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(collection(list(value,id)?,c,|value,c|{let semio_framework_dsl_record::FieldValue::Text(value)=value else{return Err(invalid("native text list item required"))};c.copy_text(value)})?,close::<Vec<String>>);c.step()?;Ok(out.take())}
fn indices(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Vec<usize>,ValueError>{let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(collection(list(value,id)?,c,|value,c|<usize as DslField>::from_value_controlled(value,c))?,close::<Vec<usize>>);c.step()?;Ok(out.take())}
fn rows(used:&mut usize,count:usize,maximum:usize)->Result<(),ValueError>{*used=used.checked_add(count).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"native owned row census overflow"))?;if *used>maximum{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"native owned row census exceeds caller limit"))}Ok(())}

fn node(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Node,ValueError>{let value=record(value,6)?;c.scoped_stage(|c|{c.begin_stage(7)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Node{kind:String::new(),integer:None,real:None,text:None,reference:None,name:None,children:Vec::new()},close::<Node>);let n=out.as_mut();n.kind=text(value,0,c)?;n.integer=optional_scalar(value,1,c)?;n.real=optional_scalar(value,2,c)?;n.text=optional_text(value,3,c)?;n.reference=optional_scalar(value,4,c)?;n.name=optional_text(value,5,c)?;n.children=indices(value,6,c)?;Ok(out.take())})}
fn complex(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Complex,ValueError>{let value=record(value,1)?;c.scoped_stage(|c|{c.begin_stage(2)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Complex{name:String::new(),arguments:Vec::new()},close::<Complex>);out.as_mut().name=text(value,0,c)?;out.as_mut().arguments=indices(value,1,c)?;Ok(out.take())})}
fn entity(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Entity,ValueError>{let value=record(value,3)?;c.scoped_stage(|c|{c.begin_stage(4)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Entity{id:0,name:String::new(),arguments:Vec::new(),complex:Vec::new()},close::<Entity>);out.as_mut().id=scalar(value,0,c)?;out.as_mut().name=text(value,1,c)?;out.as_mut().arguments=indices(value,2,c)?;out.as_mut().complex=collection(list(value,3)?,c,complex)?;c.step()?;Ok(out.take())})}
fn census(value:&RecordValue,maximum:usize,c:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{closed(value,12)?;let mut used=2;rows(&mut used,0,maximum)?;for id in [1,5,6,10]{rows(&mut used,list(value,id)?.len(),maximum)?;}c.scoped_stage(|c|{let entities=list(value,11)?;rows(&mut used,entities.len(),maximum)?;c.begin_stage(entities.len())?;for value in entities{let value=record(value,3)?;rows(&mut used,list(value,2)?.len(),maximum)?;let complexes=list(value,3)?;rows(&mut used,complexes.len(),maximum)?;c.scoped_stage(|c|{c.begin_stage(complexes.len())?;for value in complexes{rows(&mut used,list(record(value,1)?,1)?.len(),maximum)?;c.step()?;}Ok::<_,ValueError>(())})?;c.step()?;}Ok::<_,ValueError>(())})?;c.scoped_stage(|c|{let nodes=list(value,12)?;rows(&mut used,nodes.len(),maximum)?;c.begin_stage(nodes.len())?;for value in nodes{rows(&mut used,list(record(value,6)?,6)?.len(),maximum)?;c.step()?;}Ok(())})}
pub(super) fn frame(value:&RecordValue,c:&mut NativeDecodeControl<'_>,maximum:usize)->Result<Frame,ValueError>{census(value,maximum,c)?;c.scoped_stage(|c|{c.begin_stage(13)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Frame{schema:String::new(),description:Vec::new(),implementation_level:String::new(),file_name:String::new(),timestamp:String::new(),author:Vec::new(),organization:Vec::new(),preprocessor_version:String::new(),originating_system:String::new(),authorization:String::new(),file_schema:Vec::new(),entities:Vec::new(),values:Vec::new()},close::<Frame>);let f=out.as_mut();f.schema=text(value,0,c)?;f.description=texts(value,1,c)?;f.implementation_level=text(value,2,c)?;f.file_name=text(value,3,c)?;f.timestamp=text(value,4,c)?;f.author=texts(value,5,c)?;f.organization=texts(value,6,c)?;f.preprocessor_version=text(value,7,c)?;f.originating_system=text(value,8,c)?;f.authorization=text(value,9,c)?;f.file_schema=texts(value,10,c)?;f.entities=collection(list(value,11)?,c,entity)?;c.step()?;f.values=collection(list(value,12)?,c,node)?;c.step()?;Ok(out.take())})}
